<?php
require_once __DIR__.'/../../backend/rutas_aprendizaje.php';
$uid=(int)$_SESSION['usuario_perfil_id'];
$rutaActiva=$conn->query("SELECT r.*,ur.item_actual_id FROM usuario_rutas ur JOIN rutas_aprendizaje r ON r.id=ur.ruta_id WHERE ur.usuario_id={$uid} AND ur.es_activa=1 LIMIT 1")->fetch_assoc();
if(!$rutaActiva)$rutaActiva=$conn->query("SELECT r.*,NULL item_actual_id FROM rutas_aprendizaje r WHERE r.estado='publicada' AND r.es_empieza_aqui=1 LIMIT 1")->fetch_assoc();
$itemsRuta=$rutaActiva?ruta_items($conn,(int)$rutaActiva['id']):[];$siguienteRuta=null;$completos=0;
foreach($itemsRuta as $it){if(ruta_item_completado($conn,$uid,$it))$completos++;elseif(!$siguienteRuta)$siguienteRuta=$it;}
$pctRuta=count($itemsRuta)?(int)round($completos/count($itemsRuta)*100):0;
$stmt=$conn->prepare("SELECT c.titulo,c.slug,c.imagen_portada,l.id leccion_id,l.titulo leccion_titulo,p.ultimo_acceso,
 (SELECT COUNT(*) FROM lecciones lx WHERE lx.curso_id=c.id AND lx.estado_publicacion='publicado') total,
 (SELECT COUNT(*) FROM progreso px JOIN lecciones lx2 ON lx2.id=px.leccion_id WHERE px.usuario_id=? AND lx2.curso_id=c.id AND px.completado=1) hechas
 FROM progreso p JOIN lecciones l ON l.id=p.leccion_id JOIN cursos c ON c.id=l.curso_id
 WHERE p.usuario_id=? ORDER BY p.ultimo_acceso DESC LIMIT 1");$stmt->bind_param('ii',$uid,$uid);$stmt->execute();$continuar=$stmt->get_result()->fetch_assoc();$stmt->close();
$stmt=$conn->prepare("SELECT e.titulo,e.slug,e.fecha_inicio FROM evento_inscripciones ei JOIN eventos e ON e.id=ei.evento_id WHERE ei.usuario_id=? AND ei.estado<>'cancelado' AND e.fecha_inicio>=NOW() ORDER BY e.fecha_inicio LIMIT 1");$stmt->bind_param('i',$uid);$stmt->execute();$proximoEvento=$stmt->get_result()->fetch_assoc();$stmt->close();
?>
<h1 class="h3 fw-bold mb-1">Empieza aquí</h1><p class="text-muted mb-4">Tu siguiente paso, sin tener que buscarlo.</p>
<?php if($rutaActiva):?><div class="card border-0 shadow-sm p-4 mb-4" style="background:linear-gradient(135deg,#fff8ec,#fff)"><span class="small fw-bold text-uppercase" style="color:#a9570c">Ruta recomendada</span><h2 class="h4 mt-1"><?=htmlspecialchars($rutaActiva['titulo'])?></h2><div class="progress my-2"><div class="progress-bar" style="width:<?=$pctRuta?>%;background:#f7931e"></div></div><p class="small text-muted"><?=$pctRuta?>% completado</p><div><?php if($siguienteRuta):?><a class="btn" style="background:#f7931e;color:#fff" href="../index.php?action=<?=$siguienteRuta['tipo_contenido']?>&slug=<?=urlencode($siguienteRuta['slug'])?>&ruta=<?=urlencode($rutaActiva['slug'])?>"><?=$pctRuta?'Continuar ruta':'Comenzar ruta'?> →</a><?php endif;?> <a class="btn btn-outline-secondary" href="../index.php?action=ruta&slug=<?=urlencode($rutaActiva['slug'])?>">Ver mapa</a></div></div><?php endif;?>
<div class="row g-4"><div class="col-lg-7"><?php if($continuar):$p=$continuar['total']?(int)round($continuar['hechas']/$continuar['total']*100):0;?><div class="card h-100 border-0 shadow-sm p-4"><span class="small text-muted">Continuar aprendiendo</span><h2 class="h5 mt-2"><?=htmlspecialchars($continuar['titulo'])?></h2><p class="mb-2">Última lección: <?=htmlspecialchars($continuar['leccion_titulo'])?></p><div class="progress mb-2"><div class="progress-bar" style="width:<?=$p?>%;background:#F6C500"></div></div><p class="small text-muted"><?=$p?>% · <?=max(0,(int)$continuar['total']-(int)$continuar['hechas'])?> lecciones pendientes</p><a class="btn align-self-start" style="background:#F6C500;color:#171717" href="../index.php?action=leccion&id=<?=(int)$continuar['leccion_id']?>">Continuar →</a></div><?php else:?><div class="card h-100 border-0 shadow-sm p-4"><h2 class="h5">Curso recomendado para comenzar</h2><p class="text-muted">Elige tu primer contenido desde la ruta recomendada o el catálogo.</p><a href="../index.php?action=cursos">Explorar cursos →</a></div><?php endif;?></div><div class="col-lg-5"><div class="card border-0 shadow-sm p-4 mb-3"><span class="small text-muted">Próximo evento</span><?php if($proximoEvento):?><strong class="my-2"><?=htmlspecialchars($proximoEvento['titulo'])?></strong><span class="small mb-2"><?=date('d/m/Y H:i',strtotime($proximoEvento['fecha_inicio']))?></span><a href="../index.php?action=evento&slug=<?=urlencode($proximoEvento['slug'])?>">Ver evento →</a><?php else:?><p class="text-muted mb-1">No tienes eventos próximos.</p><a href="../index.php?action=eventos">Ver eventos →</a><?php endif;?></div><div class="card border-0 shadow-sm p-4"><span class="small text-muted">Comunidad</span><strong class="my-2">Aprende también conversando</strong><a href="../foro/">Ir al foro →</a></div></div></div>
